import { chromium } from 'playwright'
const URL = 'http://127.0.0.1:8093/wechatapph5/#/pages-survey/index'

// 模拟一道“星级评分”题（star/type=4），评星位于答案区底部
function buildResp(scale) {
  return { MtplQuestionnaireModel: { description: '尊敬的园区各小区居民：您好！为了在苏州工业园区物业服务企业规范化考评中全面了解广大业主（对物业管理服务的需求，提高物业服务的认知度和满意度，根据考评办法，请您如实填写。', totalCount: 1046, joinedCount: 0,
    examsList: [ { no: '1', type: 4, topic: '您对本小区物业管理服务的期望如何？', options: [], required: 1 } ] } }
}

const scale = Number(process.argv[2] || '1.5')
const browser = await chromium.launch({ channel: 'msedge' })
const context = await browser.newContext({ viewport: { width: 393, height: 851 }, isMobile: true, hasTouch: true, deviceScaleFactor: 3,
  userAgent: 'Mozilla/5.0 (Linux; Android 13; MI 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36' })
const page = await context.newPage()
await page.route('**/api/**', async (r) => {
  const u = r.request().url(); let b = '{}'
  if (u.includes('SmQuestionnaireGoHandleApp')) b = JSON.stringify(buildResp(scale))
  else if (u.includes('SmQuestionnaireReplyRate')) b = JSON.stringify({ rate: 0, totalHouse: 1046, replyHouse: 0 })
  await r.fulfill({ status: 200, contentType: 'application/json', body: b })
})
await page.goto(URL, { waitUntil: 'networkidle', timeout: 30000 })
await page.waitForSelector('.survey-page-answer-scrollable', { timeout: 15000 })

// 模拟微信关怀模式：放大字号（uni-app rpx 不变，但微信会放大 px 文本/整体）
await page.evaluate((s) => {
  document.documentElement.style.fontSize = (16 * s) + 'px'
  // 微信关怀模式常见：对文本做 text-size-adjust 放大
  document.body.style.webkitTextSizeAdjust = Math.round(s * 100) + '%'
  // 放大页面主要文本字体，逼近真实关怀模式效果
  const st = document.createElement('style')
  st.textContent = `
    .survey-page-title{font-size:${36*s/2}px !important;line-height:${52*s/2}px !important}
    .survey-page-desc{font-size:${26*s/2}px !important;line-height:${40*s/2}px !important}
    .survey-page-area-name{font-size:${36*s/2}px !important}
    .survey-page-question-title{font-size:${32*s/2}px !important;line-height:${48*s/2}px !important}
    .survey-page-stat-label{font-size:${28*s/2}px !important}
    .survey-page-stat-value{font-size:${34*s/2}px !important}
    .survey-page-progress-label{font-size:${24*s/2}px !important}
    .survey-page-progress-value{font-size:${28*s/2}px !important}
  `
  document.head.appendChild(st)
}, scale)
await page.waitForTimeout(600)

const m = await page.evaluate(() => {
  const header = document.querySelector('.survey-page-header')
  const content = document.querySelector('.survey-page-content')
  const scroll = document.querySelector('.survey-page-answer-scrollable')
  const footer = document.querySelector('.survey-page-footer')
  const star = document.querySelector('.survey-page-star-section')
  const rect = (el) => el ? { h: Math.round(el.getBoundingClientRect().height), top: Math.round(el.getBoundingClientRect().top), bottom: Math.round(el.getBoundingClientRect().bottom) } : null
  // 找真正可滚内部容器
  const all = document.querySelectorAll('.survey-page-answer-scrollable, .survey-page-answer-scrollable *')
  let sc = null
  for (const el of all) { const cs = getComputedStyle(el); if ((cs.overflowY==='auto'||cs.overflowY==='scroll') && el.scrollHeight > el.clientHeight+2){ sc = el; break } }
  return {
    viewportH: window.innerHeight,
    header: rect(header), content: rect(content), scroll: rect(scroll), footer: rect(footer), star: rect(star),
    scrollInnerClientH: sc ? sc.clientHeight : null,
    scrollInnerScrollH: sc ? sc.scrollHeight : null,
  }
})
console.log(JSON.stringify(m, null, 2))
await page.screenshot({ path: `caremode-${scale}.png` })
await browser.close()

